  const validItems = [];

  for (const item of items) {
    const rawPhone = item.json.phoneUnformatted || '';

    // Remove tudo que não for número
    let digits = rawPhone.replace(/\D/g, '');

    if (!digits) continue;

    // Remove código do país se já vier com 55
    if (digits.startsWith('55') && digits.length >= 12) {
      digits = digits.substring(2);
    }

    // Normaliza 10 dígitos (formato antigo)
    if (digits.length === 10) {
      const primeiroAposDDD = digits.charAt(2);
      if (['6', '7', '8', '9'].includes(primeiroAposDDD)) {
        digits = digits.substring(0, 2) + '9' + digits.substring(2);
      } else {
        continue; // fixo, descarta
      }
    }

    // Deve ter exatamente 11 dígitos
    if (digits.length !== 11) continue;

    // Deve ser celular (3º dígito = 9)
    if (digits.charAt(2) !== '9') continue;

    // DDD válido entre 11 e 99
    const ddd = parseInt(digits.substring(0, 2));
    if (ddd < 11 || ddd > 99) continue;

    validItems.push({
      json: {
        ...item.json,
        phoneUnformatted: '55' + digits
      }
    });
  }

  return validItems;

