// v46 — enriquecer_leads com IA (OpenAI web_search)
// Ordem de tentativas por lead:
//  1. Tem telefone → valida celular BR → passa ou descarta
//  2. Sem fone + tem site → raspa HTML (wa.me/ ou padrão) → valida → passa
//  3. Sem fone (falhou acima) → IA busca telefone pelo nome+cidade → valida → passa
//  4. Sem resultado → descarta

const OPENAI_KEY = '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';

const allItems = $input.all();
const quantidade_bruta = allItems.length;
const resultado = [];

// Valida e normaliza para celular BR (11 dígitos DD+9+8)
// Retorna string normalizada sem DDI, ou null se inválido
function normalizarCelular(raw) {
  let d = raw.replace(/\D/g, '');
  if (d.startsWith('55') && d.length >= 12) d = d.substring(2);
  if (d.length === 10) {
    const t = d.charAt(2);
    if (['6','7','8','9'].includes(t)) d = d.substring(0,2) + '9' + d.substring(2);
    else return null;
  }
  if (d.length !== 11) return null;
  if (d.charAt(2) !== '9') return null;
  const ddd = parseInt(d.substring(0,2));
  if (ddd < 11 || ddd > 99) return null;
  return d;
}

// Chama a OpenAI Responses API com web_search_preview
// Retorna o número encontrado (normalizado) ou null
async function buscarTelefoneIA(nome, endereco, cidade) {
  try {
    const prompt = `Busque o número de WhatsApp ou celular da empresa: "${nome}", localizada em ${endereco ? endereco + ', ' : ''}${cidade}, Brasil.
Responda APENAS com o número de telefone (com DDD), sem formatação, sem texto adicional.
Se não encontrar com certeza, responda: não encontrado`;

    const resp = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/responses',
      headers: {
        'Authorization': `Bearer ${OPENAI_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        tools: [{ type: 'web_search_preview' }],
        input: prompt,
      }),
      timeout: 20000,
    });

    // Extrai texto da resposta
    const outputItems = resp.output || [];
    const msg = outputItems.find(o => o.type === 'message');
    const txt = (msg?.content?.find(c => c.type === 'output_text')?.text || '').trim();

    if (!txt || txt.toLowerCase().includes('não encontrado') || txt.toLowerCase().includes('nao encontrado')) {
      return null;
    }

    // Tenta extrair um número do texto retornado
    const nums = txt.match(/[\d\s()\-+]+/g) || [];
    for (const n of nums) {
      const cel = normalizarCelular(n);
      if (cel) return cel;
    }
    return null;
  } catch(e) {
    return null; // falha silenciosa
  }
}

for (const item of allItems) {
  const rawTel = (item.json.phone || item.json.phoneUnformatted || '');
  const website = item.json.website || '';
  const nome    = item.json.title || item.json.empresa || '';
  const cidade  = item.json.city || item.json.cidade || '';
  const end     = item.json.address || item.json.endereco || '';

  // ── Etapa 1: tem telefone → valida ──────────────────────────
  if (rawTel.replace(/\D/g, '').length >= 10) {
    const cel = normalizarCelular(rawTel);
    if (cel) {
      resultado.push({ json: Object.assign({}, item.json, { phoneUnformatted: '55' + cel }) });
    } else {
      // Telefone inválido (fixo?) → tenta IA antes de descartar
      const celIA = await buscarTelefoneIA(nome, end, cidade);
      if (celIA) {
        resultado.push({ json: Object.assign({}, item.json, {
          phoneUnformatted: '55' + celIA,
          phone: celIA,
          _fonte_telefone: 'ia_websearch',
        })});
      }
    }
    continue;
  }

  // ── Etapa 2: sem telefone + tem site → raspa HTML ────────────
  let foundByHtml = false;
  if (website) {
    try {
      const response = await $helpers.httpRequest({ method: 'GET', url: website, timeout: 8000 });
      const html = (typeof response === 'string') ? response : (response.body || response.data || JSON.stringify(response));

      // wa.me/ (WhatsApp direto)
      const waMatch = html.match(/wa\.me\/(\d{10,15})/);
      if (waMatch) {
        const cel = normalizarCelular(waMatch[1]);
        if (cel) {
          resultado.push({ json: Object.assign({}, item.json, {
            phoneUnformatted: '55' + cel, phone: cel, _fonte_telefone: 'website_wame',
          })});
          foundByHtml = true;
        }
      }

      if (!foundByHtml) {
        const pats = html.match(/\(?\d{2}\)?\s*9?\d{4}[-\s]?\d{4}/g) || [];
        for (const p of pats) {
          const cel = normalizarCelular(p);
          if (cel) {
            resultado.push({ json: Object.assign({}, item.json, {
              phoneUnformatted: '55' + cel, phone: cel, _fonte_telefone: 'website_html',
            })});
            foundByHtml = true;
            break;
          }
        }
      }
    } catch(e) { /* site inacessível */ }
  }

  if (foundByHtml) continue;

  // ── Etapa 3: IA busca o telefone ────────────────────────────
  if (nome && cidade) {
    const celIA = await buscarTelefoneIA(nome, end, cidade);
    if (celIA) {
      resultado.push({ json: Object.assign({}, item.json, {
        phoneUnformatted: '55' + celIA,
        phone: celIA,
        _fonte_telefone: 'ia_websearch',
      })});
      continue;
    }
  }

  // ── Etapa 4: descarta ────────────────────────────────────────
}

if (resultado.length === 0) {
  return [{ json: { _sem_resultado: true, _meta_bruta: quantidade_bruta, _meta_filtrada: 0 } }];
}

return resultado.map((item, idx) => ({
  json: Object.assign({}, item.json, {
    _meta_bruta:    idx === 0 ? quantidade_bruta : undefined,
    _meta_filtrada: idx === 0 ? resultado.length  : undefined,
  })
}));

const allItems = $input.all();
const items = allItems.filter(i => !i.json._sem_resultado);
const tipoLoja = $('definir_termos').first().json.tipo_loja || '';
const quantidadePedida = $('definir_termos').first().json.quantidade_pedida || items.length;

if (items.length === 0) {
  return [{ json: { _sem_resultado: true, _total_entregue: 0, _tipo_loja: tipoLoja } }];
}

const entrega = items.slice(0, quantidadePedida);
const reserva  = items.slice(quantidadePedida);

return [
  // Primeiros N → LOCALIZADOS (aparecem no painel de aprovação)
  ...entrega.map((item, idx) => {
    const json = Object.assign({}, item.json);
    delete json._meta_bruta;
    delete json._meta_filtrada;
    json._status_final    = 'LOCALIZADOS';
    json._tipo_loja       = tipoLoja;
    json._total_entregue  = entrega.length;
    return { json };
  }),
  // Resto → RESERVA (salvos no banco mas não aparecem no painel)
  ...reserva.map(item => {
    const json = Object.assign({}, item.json);
    delete json._meta_bruta;
    delete json._meta_filtrada;
    json._status_final    = 'RESERVA';
    json._tipo_loja       = tipoLoja;
    json._total_entregue  = entrega.length;
    return { json };
  }),
];

const body = $('receber_busca_dashboard').first().json.body;
const tipoLoja = body.tipo_loja || '';
const cidade = body.cidade || '';
const estado = body.estado || '';

const HASHTAGS = {
  'Lojas de artigos esportivos': ['lojaesportiva', 'materialesportivo', 'bolasdefutebol', 'patins', 'beachtennis'],
  'Lojas de brinquedos': ['lojadebrinquedos', 'brinquedosinfantis', 'lojakids', 'brinquedos'],
  'Lojas de Variedades/1,99/miudezas/bazares': ['lojavariedades', 'bazar', 'importados', 'loja199', 'bazarvariedades'],
  'Supermercados': ['supermercado', 'mercadinho', 'minimercado'],
  'Hipermercados': ['hipermercado', 'supermercado', 'atacadista'],
  'Eletroportáteis/eletrônicos': ['lojaeletronicos', 'lojacelulares', 'techstore', 'eletronicos'],
};

const hashtags = HASHTAGS[tipoLoja] || ['lojavariedades', 'lojaesportiva', 'lojadebrinquedos'];
const searchTerms = hashtags.map(h => `#${h} ${cidade}`);

return [{
  json: {
    search_id: body.search_id,
    cidade,
    estado,
    tipo_loja: tipoLoja,
    quantidade: parseInt(body.quantidade) || 30,
    fonte: 'instagram',
    hashtags,
    searchTerms,
    locationQuery: `${cidade}, ${estado}, Brasil`,
  }
}];

const items = $input.all();
const results = [];
const seen = new Set();

for (const item of items) {
  const profile = item.json;
  const bio = profile.biography || profile.bio || profile.ownerBiography || '';
  const username = profile.username || profile.ownerUsername || '';
  const followers = profile.followersCount || profile.ownerFollowersCount || profile.followers || 0;
  const nome = profile.fullName || profile.ownerFullName || profile.name || username;
  const website = profile.externalUrl || profile.ownerExternalUrl || profile.website || '';

  if (!username) continue;

  const phoneRegex = /(?:\+55\s?)?(?:\(?\d{2}\)?\s?)(?:9\s?)?\d{4}[-\s]?\d{4}/g;
  const phones = bio.match(phoneRegex);

  let telefone = null;
  let _fonte_telefone = 'instagram_username';

  if (phones && phones.length > 0) {
    let raw = phones[0].replace(/\D/g, '');
    if (raw.startsWith('55') && raw.length >= 12) raw = raw.substring(2);
    if (raw.length === 10) {
      const firstAfterDDD = raw.charAt(2);
      if (['6','7','8','9'].includes(firstAfterDDD)) {
        raw = raw.substring(0,2) + '9' + raw.substring(2);
      } else {
        raw = null;
      }
    }
    if (raw && raw.length === 11 && raw.charAt(2) === '9') {
      telefone = '55' + raw;
      _fonte_telefone = 'instagram_bio';
    }
  }

  // Fallback: sem telefone valido -> usa @username como identificador
  if (!telefone) {
    telefone = '@' + username;
  }

  if (seen.has(telefone)) continue;
  seen.add(telefone);

  results.push({
    json: {
      empresa: nome,
      telefone,
      website,
      cidade: $('definir_termos_instagram').first().json.cidade,
      estado: $('definir_termos_instagram').first().json.estado,
      tipo_loja: $('definir_termos_instagram').first().json.tipo_loja,
      search_id: $('definir_termos_instagram').first().json.search_id,
      fonte: 'instagram',
      instagram_handle: username,
      instagram_followers: followers,
      status: 'LOCALIZADOS',
      _status_final: 'LOCALIZADOS',
      _tipo_loja: $('definir_termos_instagram').first().json.tipo_loja,
      _fonte_telefone,
    }
  });
}

return results.length > 0 ? results : [{ json: { _empty: true } }];
